function SearchBox({value,onChange,placeholder}:{value:string;onChange:(v:string)=>void;placeholder:string}){return <label className="search-box"><Search size={16}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/>{value&&<button className="icon-button" aria-label="Очистить поиск" onClick={()=>onChange('')}><X size={14}/></button>}</label>;}
function Dialog({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){
 const ref=useRef<HTMLDivElement>(null),closeRef=useRef(onClose);closeRef.current=onClose;
 useEffect(()=>{const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.querySelector<HTMLElement>('input,select,button')?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const nodes=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,a[href]')||[]);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',handler);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',handler);previous?.focus();};},[]);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div ref={ref} role="dialog" aria-modal="true" aria-labelledby="dialog-title" className={'dialog '+(wide?'wide':'')}><div className="dialog-heading"><h2 id="dialog-title">{title}</h2><button className="icon-button" aria-label="Закрыть" onClick={onClose}><X size={20}/></button></div>{children}</div></div>;
}

function Editor({modal,data,busy,serverError,onClose,onSave,onError,onHistory,onReveal,onMove,onPaidPeriod,onArchive}:{modal:Modal;data:Data;busy:boolean;serverError:string;onClose:()=>void;onSave:(path:string,method:string,body:unknown)=>Promise<boolean>;onError:(s:string)=>void;onHistory:(m:Member)=>void;onReveal:(type:'members'|'resources',id:number,title:string)=>void;onMove:(m:Member)=>void;onPaidPeriod:(m:Member)=>void;onArchive:(m:Member)=>void}){
 const {kind,item}=modal,isEdit=!!item&&!['payment','renew-family','renew-resource','move','paid-period'].includes(kind);
 const familyOptions=data.families.filter(f=>!f.archived).map(f=>({value:String(f.id),label:`${f.name} · ${f.member_count}/6`}));
 const currencyOptions=['BYN','USD','RUB'].map(value=>({value,label:value}));
 const member=item&&'spotify_price' in item?item as Member:undefined;
 const renewal=kind.startsWith('renew');
 const titles:Record<FormKind,string>={family:isEdit?'Редактировать семью':'Новая семья',member:isEdit?'Карточка участника':'Новый участник',resource:isEdit?'Редактировать ресурс':'Новый ресурс VPN',payment:'Добавить оплату','renew-family':'Продление Spotify','renew-resource':'Продление ресурса',account:isEdit?'Редактировать счёт':'Новый счёт ЕРИП',move:'Перенести участника',rate:'Курс валюты','paid-period':'Учесть прежнюю оплату'};
 const [values,setValues]=useState<Record<string,string|boolean|string[]>>(()=>{
   const initial:Record<string,string|boolean|string[]>={};if(isEdit&&item)Object.entries(item).forEach(([k,v])=>{if(Array.isArray(v))initial[k]=v.map(String);else initial[k]=v===null?'':typeof v==='number'?String(v):v;});
   if(kind==='family')Object.assign(initial,{started_on:initial.started_on||today(),paid_until:initial.paid_until||today(),currency:initial.currency||'USD',cost_months:initial.cost_months||'1'});
   if(kind==='member')Object.assign(initial,{family:initial.family||String(modal.family||familyOptions[0]?.value||''),joined_on:initial.joined_on||today(),spotify_price:initial.spotify_price||'12',vpn_price:initial.vpn_price||'4'});
   if(kind==='resource')Object.assign(initial,{kind:initial.kind||'vps',currency:initial.currency||'USD',cost_months:initial.cost_months||'1',paid_until:initial.paid_until||today(),families:initial.families||[]});
   if(kind==='payment'){const m=member||data.members.find(m=>m.active&&!m.is_free&&(!modal.family||m.family===modal.family));Object.assign(initial,{member:String(m?.id||''),service:'spotify',months:'1',amount:m?.spotify_price||'0',paid_on:today()});}
   if(renewal&&item&&'cost' in item)Object.assign(initial,{amount:(Number(item.cost)/item.cost_months).toFixed(2),currency:item.currency,paid_on:today(),months:'1'});
   if(kind==='paid-period')Object.assign(initial,{service:'spotify',paid_until:member?.spotify_until||today(),note:''});
   if(kind==='move')Object.assign(initial,{family:familyOptions.find(f=>f.value!==String(member?.family))?.value||'',email:''});
   if(kind==='rate'){const currency=modal.family===1?'USD':'RUB';const rate=data.rates.find(r=>r.currency===currency);Object.assign(initial,{currency,byn_per_unit:rate?.byn_per_unit||''});}
   return initial;
 });
 const [formError,setFormError]=useState('');
 const selectedMember=data.members.find(m=>String(m.id)===values.member);
 const existingOwner=data.members.find(m=>m.active&&m.is_owner&&String(m.family)===String(values.family)&&m.id!==member?.id);
 function update(name:string,value:string|boolean|string[]){setValues(v=>{const next={...v,[name]:value};if(kind==='paid-period'&&name==='service')next.paid_until=(value==='vpn'?member?.vpn_until:member?.spotify_until)||today();if(kind==='payment'&&['member','service','months'].includes(name)){const m=data.members.find(m=>String(m.id)===String(next.member));if(m){if(!m.needs_vpn)next.service='spotify';next.amount=String(Number(next.service==='vpn'?m.vpn_price:m.spotify_price)*Number(next.months||1));}}if(kind==='member'&&name==='family'&&data.members.some(m=>m.active&&m.is_owner&&String(m.family)===String(value)&&m.id!==member?.id))next.is_owner=false;if(renewal&&name==='months'&&item&&'cost' in item)next.amount=(Number(item.cost)/item.cost_months*Number(value||1)).toFixed(2);return next;});}
 const fields:Field[]=kind==='family'?[
 {name:'name',label:'Название семьи',required:true},{name:'account',label:'Счёт ЕРИП',type:'select',options:[{value:'',label:'Не привязан'},...data.accounts.map(a=>({value:String(a.id),label:a.name}))]},
 {name:'started_on',label:'Дата оформления',type:'date',required:true},{name:'paid_until',label:'Семья оплачена до',type:'date',required:true},
 {name:'cost',label:'Себестоимость подписки',type:'number',min:'0',step:'0.01',required:true},{name:'currency',label:'Валюта расходов',type:'select',options:currencyOptions},
 {name:'cost_months',label:'За сколько месяцев эта стоимость',type:'number',min:'1',max:'120',required:true},{name:'invite_url',label:'Ссылка приглашения',type:'url'},
 {name:'address',label:'Адрес семьи',type:'textarea',wide:true},{name:'notes',label:'Заметки',type:'textarea',wide:true}
 ]:kind==='member'?[
 {name:'name',label:'Имя',required:true},{name:'family',label:'Семья',type:'select',options:familyOptions,required:true},
 {name:'email',label:'Почта Spotify',type:'email',required:true},{name:'password',label:isEdit?'Новый пароль (оставь пустым, чтобы сохранить)':'Пароль аккаунта',type:'password'},
 {name:'contact',label:'Контакт / Telegram'},{name:'joined_on',label:'Дата присоединения',type:'date',required:true},
 {name:'is_owner',label:'Владелец семьи',type:'checkbox'},{name:'is_free',label:'Бесплатное участие',type:'checkbox'},{name:'needs_vpn',label:'Нужен VPN',type:'checkbox'},
 {name:'spotify_price',label:'Spotify · BYN в месяц',type:'number',min:'0',step:'0.01',required:true},{name:'vpn_price',label:'VPN · BYN в месяц',type:'number',min:'0',step:'0.01',required:true},...(!isEdit?[{name:'spotify_until',label:'Spotify уже оплачен до',type:'date',min:String(values.joined_on)},{name:'vpn_until',label:'VPN уже оплачен до',type:'date',min:String(values.joined_on)}]:[]),{name:'notes',label:'Заметки',type:'textarea',wide:true}
 ]:kind==='resource'?[
 {name:'name',label:'Название',required:true},{name:'kind',label:'Тип ресурса',type:'select',options:[{value:'vps',label:'VPS-сервер'},{value:'proxy',label:'RU-прокси'}]},
 {name:'service_url',label:'Сайт сервиса',type:'url'},{name:'login',label:'Логин / почта'},
 {name:'password',label:isEdit?'Новый пароль (пусто — сохранить)':'Пароль',type:'password'},{name:'paid_until',label:'Оплачен до',type:'date',required:true},
 {name:'cost',label:'Себестоимость',type:'number',min:'0',step:'0.01',required:true},{name:'currency',label:'Валюта',type:'select',options:currencyOptions},
 {name:'cost_months',label:'Стоимость за месяцев',type:'number',min:'1',max:'120',required:true},{name:'notes',label:'Заметки',type:'textarea',wide:true}
 ]:kind==='paid-period'?[
 {name:'service',label:'Услуга',type:'select',options:[{value:'spotify',label:'Spotify'},...(member?.needs_vpn?[{value:'vpn',label:'VPN'}]:[])]},
 {name:'paid_until',label:'Уже оплачено до',type:'date',required:true,min:member?.joined_on},
 {name:'note',label:'Почему меняем срок',type:'textarea',wide:true,required:true}
 ]:kind==='payment'?[
 {name:'member',label:'Участник',type:'select',required:true,options:data.members.filter(m=>m.active&&!m.is_free&&(!modal.family||m.family===modal.family)).map(m=>({value:String(m.id),label:`${m.name} · ${m.family_name}`}))},
 {name:'service',label:'Услуга',type:'select',options:[{value:'spotify',label:'Spotify'},...(selectedMember?.needs_vpn?[{value:'vpn',label:'VPN'}]:[])]},
 {name:'months',label:'Количество месяцев',type:'number',min:'1',max:'120',required:true},{name:'amount',label:'Получено · BYN',type:'number',min:'0',step:'0.01',required:true},
 {name:'paid_on',label:'Дата поступления',type:'date',required:true,max:today()},{name:'note',label:'Комментарий',type:'textarea',wide:true}
 ]:renewal?[
 {name:'amount',label:'Фактически потрачено',type:'number',min:'0',step:'0.01',required:true},{name:'currency',label:'Валюта расхода',type:'select',options:currencyOptions},
 {name:'paid_on',label:'Дата расхода',type:'date',required:true,max:today()},{name:'months',label:'На сколько месяцев продлить',type:'number',min:'1',max:'120',required:true},
 {name:'note',label:'Комментарий',type:'textarea',wide:true}
 ]:kind==='account'?[
 {name:'name',label:'Название счёта',required:true},{name:'number',label:'Номер / реквизиты ЕРИП',required:true},{name:'instructions',label:'Инструкция оплаты',type:'textarea',wide:true}
 ]:kind==='move'?[
 {name:'family',label:'Новая семья',type:'select',required:true,options:familyOptions.filter(f=>f.value!==String(member?.family))},{name:'email',label:'Новая почта Spotify',type:'email',required:true}
 ]:[{name:'currency',label:'Валюта',type:'select',options:currencyOptions.filter(c=>c.value!=='BYN')},{name:'byn_per_unit',label:'BYN за 1 единицу валюты',type:'number',step:'0.00000001',min:'0.00000001',required:true}];
 async function submit(e:FormEvent){e.preventDefault();setFormError('');const body:Record<string,unknown>={};for(const f of fields){body[f.name]=f.type==='checkbox'?!!values[f.name]:values[f.name]??'';if(['family','member','account','months','cost_months'].includes(f.name))body[f.name]=body[f.name]===''?null:Number(body[f.name]);}
   if(isEdit&&body.password==='')delete body.password;
   if(kind==='member'){for(const field of ['spotify_until','vpn_until']){if(body[field]===''||values.is_free||(field==='vpn_until'&&!values.needs_vpn))delete body[field];}}
   if(kind==='resource')body.families=(values.families as string[]||[]).map(Number);
   let path='',method=isEdit?'PATCH':'POST';
   if(kind==='family')path='families/';if(kind==='member')path='members/';if(kind==='resource')path='resources/';if(kind==='account')path='accounts/';
   if(isEdit)path+=item!.id+'/';
   if(kind==='payment')path='payments/';
   if(kind==='paid-period')path=`members/${member!.id}/paid-period/`;
   if(renewal)path=(kind==='renew-family'?'families/':'resources/')+item!.id+'/renew/';
   if(kind==='move')path=`members/${item!.id}/move/`;
   if(kind==='rate'){const existing=data.rates.find(r=>r.currency===values.currency);path=existing?`rates/${existing.id}/`:'rates/';method=existing?'PATCH':'POST';}
   if(!await onSave(path,method,body))setFormError('Не удалось сохранить. Проверь данные — причина показана в уведомлении кабинета.');
 }
 let preview:string|null=null;
 if(kind==='payment'&&selectedMember){const until=values.service==='vpn'?selectedMember.vpn_until:selectedMember.spotify_until;const start=[until||selectedMember.joined_on,String(values.paid_on),selectedMember.joined_on].sort().at(-1)!;const d=new Date(start+'T12:00:00');const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+Number(values.months||1));const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));const end=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;preview=`Период: ${date(start)} → ${date(end)}. Срок семьи не изменится.`;}
 return <Dialog title={titles[kind]} onClose={onClose} wide><form onSubmit={submit}>
 {renewal&&<p className="notice">{item?.name} · текущий срок: {date(item&&'paid_until' in item?item.paid_until:null)}. Продление добавит расход в историю.</p>}
 {renewal&&item&&'paid_until' in item&&<div className="notice renewal-preview"><CalendarDays size={17}/><span>Продление до <strong>{date(addMonths([item.paid_until,String(values.paid_on||today())].sort().at(-1)!,Math.max(1,Math.min(120,Number(values.months)||1))))}</strong> · {values.months||1} мес.</span></div>}
 {kind==='paid-period'&&<p className="notice">{member?.name} · текущий срок: {date(values.service==='vpn'?member?.vpn_until:member?.spotify_until)}. Укажи дату, до которой человек уже оплатил. Новое поступление денег не создаётся, доход в финансах не увеличивается. Дата вступления и срок семьи сохранятся.</p>}
 {kind==='member'&&!isEdit&&<p className="notice">Добавляешь давнего участника? Укажи настоящую дату присоединения и уже оплаченный срок. Прежние оплаты не попадут повторно в доход. Если предоплаты нет, оставь срок пустым.</p>}
 {kind==='move'&&<p className="notice">Оплаченные сроки сохранятся. Старая почта останется в истории, пароль будет очищен.</p>}
 {member&&isEdit&&<div className="member-summary"><Status until={member.spotify_until} free={member.is_free}/><span>Spotify до {date(member.spotify_until)}</span><button type="button" className="text-link" onClick={()=>onHistory(member)}><History size={14}/>История</button></div>}
 <div className="form-grid">{fields.filter(f=>kind!=='member'||(!['spotify_price','spotify_until'].includes(f.name)||!values.is_free)&&(!['vpn_price','vpn_until'].includes(f.name)||values.needs_vpn&&!values.is_free)).map(f=><label className={(f.wide?'wide-field ':'')+(f.type==='checkbox'?'checkbox-field':'field')+(['spotify_price','vpn_price'].includes(f.name)?' field-reveal':'')} key={f.name}><span>{f.label}{f.required&&<i> *</i>}{f.name==='is_owner'&&existingOwner&&<small className="owner-constraint">Уже назначен: {existingOwner.name}</small>}</span>{f.type==='select'?<SelectControl name={f.name} required={f.required} disabled={isEdit&&kind==='member'&&f.name==='family'} value={String(values[f.name]??'')} onChange={e=>update(f.name,e.target.value)}>{!f.options?.length&&<option value="">Нет доступных вариантов</option>}{f.options?.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</SelectControl>:f.type==='textarea'?<textarea name={f.name} required={f.required} value={String(values[f.name]??'')} onChange={e=>update(f.name,e.target.value)} rows={3}/>:f.type==='checkbox'?<input type="checkbox" name={f.name} disabled={f.name==='is_owner'&&!!existingOwner} checked={!!values[f.name]} onChange={e=>update(f.name,e.target.checked)}/>:<input name={f.name} type={f.type||'text'} required={f.required} min={f.min} max={f.max} step={f.step} value={String(values[f.name]??'')} autoComplete={f.type==='password'?'new-password':'off'} onChange={e=>update(f.name,e.target.value)}/>}</label>)}</div>
 {kind==='resource'&&<fieldset className="family-checks"><legend>Семьи, использующие этот VPN</legend>{data.families.filter(f=>!f.archived).map(f=><label key={f.id}><input type="checkbox" checked={(values.families as string[]||[]).includes(String(f.id))} onChange={e=>update('families',e.target.checked?[...(values.families as string[]||[]),String(f.id)]:(values.families as string[]||[]).filter(x=>x!==String(f.id)))}/>{f.name}</label>)}</fieldset>}
 {preview&&<div className="notice payment-preview"><CalendarDays size={17}/>{preview}</div>}
 {kind==='member'&&isEdit&&!!member?.paid_period_adjustments?.length&&<details className="paid-period-history"><summary>Учтённые прежние оплаты · {member.paid_period_adjustments.length}</summary>{member.paid_period_adjustments.map(a=><div className="history-row" key={a.id}><strong>{a.service==='vpn'?'VPN':'Spotify'} · {date(a.previous_until)} → {date(a.paid_until)}</strong><p>{a.note}</p></div>)}</details>}
 {kind==='payment'&&<p className="panel-note">Сумма подставляется по тарифу участника. Её можно изменить. Оплата Spotify и VPN записывается отдельно.</p>}
 {(serverError||formError)&&<p className="form-error" role="alert">{serverError||formError}</p>}
 <div className="dialog-actions"><button type="button" className="secondary" disabled={busy} onClick={onClose}>Отмена</button><button className="primary" disabled={busy}>{busy?'Сохраняем…':kind==='payment'?'Записать оплату':renewal?'Записать продление':'Сохранить'}</button></div>
 {member&&isEdit&&<div className="member-extra"><button type="button" className="text-link" onClick={()=>onReveal('members',member.id,member.name)}><Eye size={14}/>Пароль</button>{member.active&&<>{!member.is_free&&<button type="button" className="text-link" onClick={()=>onPaidPeriod(member)}><CheckCircle2 size={14}/>Учесть прежнюю оплату</button>}<button type="button" className="text-link" onClick={()=>onMove(member)}><ArrowRightLeft size={14}/>Перенести</button><button type="button" className="danger-link" onClick={()=>onArchive(member)}><Trash2 size={14}/>Убрать из семьи</button></>}</div>}
 </form></Dialog>;
}
